    private static var cache: [String: NSImage] = [:]

    static func image(_ platform: SocialPlatform, dark: Bool) -> NSImage? {
        guard let pair = svg[platform] else { return nil }
        let source = dark ? pair.dark : pair.light
        let key = "\(platform.rawValue)-\(dark)"
        if let img = cache[key] { return img }
        let img = NSImage(data: Data(source.utf8))
        cache[key] = img
        return img
    }
}

/// A platform logo that follows the light/dark appearance.
struct SocialLogoView: View {
    var platform: SocialPlatform
    var size: CGFloat = 18
    @Environment(\.colorScheme) private var scheme

    var body: some View {
        if let img = SocialLogo.image(platform, dark: scheme == .dark) {
            Image(nsImage: img)
                .resizable()
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(width: size, height: size)
        } else {
            Image(systemName: "globe").frame(width: size, height: size)
        }
    }
}
